import React, { useState } from 'react';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { DollarSign, Percent, Save, Users } from 'lucide-react';
import toast from 'react-hot-toast';
import salesRepService from '../../services/salesRepService';
import commissionService from '../../services/commissionService';

const CommissionSettings = () => {
    const [selectedRep, setSelectedRep] = useState(null);
    const [structure, setStructure] = useState('');
    const [baseSalary, setBaseSalary] = useState('');
    const [commissionPercentage, setCommissionPercentage] = useState('');
    const queryClient = useQueryClient();

    const { data: salesReps, isLoading } = useQuery({
        queryKey: ['sales-reps'],
        queryFn: () => salesRepService.getAllSalesReps()
    });

    const updateMutation = useMutation({
        mutationFn: (data) => commissionService.setCommission(data.userId, data),
        onSuccess: () => {
            toast.success('Commission structure updated');
            queryClient.invalidateQueries(['sales-reps']);
            setSelectedRep(null);
            resetForm();
        },
        onError: (error) => {
            toast.error(error.response?.data?.message || 'Failed to update commission');
        }
    });

    const resetForm = () => {
        setStructure('');
        setBaseSalary('');
        setCommissionPercentage('');
    };

    const handleSelectRep = (rep) => {
        setSelectedRep(rep);
        setStructure(rep.commission?.structure || '');
        setBaseSalary(rep.commission?.baseSalary?.toString() || '');
        setCommissionPercentage(rep.commission?.commissionPercentage?.toString() || '');
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        if (!selectedRep) return;

        updateMutation.mutate({
            userId: selectedRep.id,
            structure,
            baseSalary: parseFloat(baseSalary) || 0,
            commissionPercentage: parseFloat(commissionPercentage) || 0
        });
    };

    const getStructureLabel = (structure) => {
        const labels = {
            commission_only: 'Commission Only',
            salary_only: 'Salary Only',
            salary_plus_commission: 'Salary + Commission'
        };
        return labels[structure] || 'Not Set';
    };

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Commission Settings</h1>
                <p className="text-gray-500 dark:text-gray-400 mt-1">
                    Configure commission structures for sales representatives
                </p>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Sales Reps List */}
                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700">
                    <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                        <h3 className="font-semibold text-gray-900 dark:text-white flex items-center gap-2">
                            <Users className="h-5 w-5 text-indigo-600" />
                            Sales Representatives
                        </h3>
                    </div>
                    <div className="divide-y divide-gray-200 dark:divide-gray-700 max-h-96 overflow-y-auto">
                        {isLoading ? (
                            <div className="p-8 text-center">
                                <div className="w-8 h-8 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin mx-auto" />
                            </div>
                        ) : (
                            salesReps?.map(rep => (
                                <button
                                    key={rep.id}
                                    onClick={() => handleSelectRep(rep)}
                                    className={`w-full p-4 text-left hover:bg-gray-50 dark:hover:bg-gray-750 transition-colors ${selectedRep?.id === rep.id ? 'bg-indigo-50 dark:bg-indigo-900/20 border-l-4 border-indigo-600' : ''
                                        }`}
                                >
                                    <div className="flex items-center justify-between">
                                        <div>
                                            <p className="font-medium text-gray-900 dark:text-white">
                                                {rep.firstName} {rep.lastName}
                                            </p>
                                            <p className="text-sm text-gray-500">{rep.email}</p>
                                        </div>
                                        <span className={`text-xs px-2 py-1 rounded-full font-medium ${rep.commission
                                                ? 'bg-teal-100 text-teal-800 dark:bg-teal-900/30 dark:text-teal-400'
                                                : 'bg-gray-100 text-gray-600 dark:bg-gray-700 dark:text-gray-400'
                                            }`}>
                                            {getStructureLabel(rep.commission?.structure)}
                                        </span>
                                    </div>
                                    {rep.commission && (
                                        <div className="flex gap-3 mt-2 text-xs text-gray-500">
                                            {rep.commission.baseSalary > 0 && (
                                                <span className="flex items-center gap-1">
                                                    <DollarSign className="h-3 w-3" />
                                                    ${rep.commission.baseSalary}/mo
                                                </span>
                                            )}
                                            {rep.commission.commissionPercentage > 0 && (
                                                <span className="flex items-center gap-1">
                                                    <Percent className="h-3 w-3" />
                                                    {rep.commission.commissionPercentage}%
                                                </span>
                                            )}
                                        </div>
                                    )}
                                </button>
                            ))
                        )}
                    </div>
                </div>

                {/* Commission Form */}
                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700">
                    <div className="p-4 border-b border-gray-200 dark:border-gray-700">
                        <h3 className="font-semibold text-gray-900 dark:text-white">
                            {selectedRep ? `Edit Commission - ${selectedRep.firstName} ${selectedRep.lastName}` : 'Select a Representative'}
                        </h3>
                    </div>

                    {selectedRep ? (
                        <form onSubmit={handleSubmit} className="p-6 space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                                    Commission Structure
                                </label>
                                <select
                                    value={structure}
                                    onChange={(e) => setStructure(e.target.value)}
                                    className="w-full px-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
                                    required
                                >
                                    <option value="">Select structure</option>
                                    <option value="commission_only">Commission Only</option>
                                    <option value="salary_only">Salary Only</option>
                                    <option value="salary_plus_commission">Salary + Commission</option>
                                </select>
                            </div>

                            {(structure === 'salary_only' || structure === 'salary_plus_commission') && (
                                <motion.div
                                    initial={{ opacity: 0, height: 0 }}
                                    animate={{ opacity: 1, height: 'auto' }}
                                >
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                                        Base Salary ($/month)
                                    </label>
                                    <div className="relative">
                                        <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                                        <input
                                            type="number"
                                            value={baseSalary}
                                            onChange={(e) => setBaseSalary(e.target.value)}
                                            className="w-full pl-10 pr-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
                                            placeholder="50000"
                                            required
                                        />
                                    </div>
                                </motion.div>
                            )}

                            {(structure === 'commission_only' || structure === 'salary_plus_commission') && (
                                <motion.div
                                    initial={{ opacity: 0, height: 0 }}
                                    animate={{ opacity: 1, height: 'auto' }}
                                >
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                                        Commission Percentage (%)
                                    </label>
                                    <div className="relative">
                                        <Percent className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                                        <input
                                            type="number"
                                            value={commissionPercentage}
                                            onChange={(e) => setCommissionPercentage(e.target.value)}
                                            className="w-full pl-10 pr-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-indigo-500"
                                            placeholder="10"
                                            min="0"
                                            max="100"
                                            step="0.1"
                                            required
                                        />
                                    </div>
                                </motion.div>
                            )}

                            {structure && (
                                <motion.div
                                    initial={{ opacity: 0 }}
                                    animate={{ opacity: 1 }}
                                    className="p-4 bg-gray-50 dark:bg-gray-900 rounded-lg"
                                >
                                    <h4 className="font-medium text-gray-900 dark:text-white mb-2">Summary</h4>
                                    {structure === 'commission_only' && (
                                        <p className="text-sm text-gray-600 dark:text-gray-400">
                                            Rep earns <strong>{commissionPercentage || 0}%</strong> commission on each completed order. No base salary.
                                        </p>
                                    )}
                                    {structure === 'salary_only' && (
                                        <p className="text-sm text-gray-600 dark:text-gray-400">
                                            Rep earns <strong>${baseSalary || 0}/month</strong> fixed salary. No per-order commission.
                                        </p>
                                    )}
                                    {structure === 'salary_plus_commission' && (
                                        <p className="text-sm text-gray-600 dark:text-gray-400">
                                            Rep earns <strong>${baseSalary || 0}/month</strong> base salary plus <strong>{commissionPercentage || 0}%</strong> commission per order.
                                        </p>
                                    )}
                                </motion.div>
                            )}

                            <button
                                type="submit"
                                disabled={updateMutation.isLoading || !structure}
                                className="w-full flex items-center justify-center gap-2 px-4 py-2.5 bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg font-medium transition-colors disabled:opacity-50"
                            >
                                {updateMutation.isLoading ? (
                                    <>
                                        <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                                        Saving...
                                    </>
                                ) : (
                                    <>
                                        <Save className="h-5 w-5" />
                                        Save Commission Structure
                                    </>
                                )}
                            </button>
                        </form>
                    ) : (
                        <div className="p-8 text-center text-gray-500">
                            <Users className="h-12 w-12 mx-auto mb-3 text-gray-300" />
                            <p>Select a sales representative from the list to configure their commission.</p>
                        </div>
                    )}
                </div>
            </div>

            {/* Commission Structures Overview */}
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6">
                <h3 className="font-semibold text-gray-900 dark:text-white mb-4">Commission Structures Overview</h3>
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                    {[
                        { structure: 'commission_only', label: 'Commission Only', description: 'Earn per order completed', color: 'indigo', count: salesReps?.filter(r => r.commission?.structure === 'commission_only').length || 0 },
                        { structure: 'salary_only', label: 'Salary Only', description: 'Fixed monthly salary', color: 'emerald', count: salesReps?.filter(r => r.commission?.structure === 'salary_only').length || 0 },
                        { structure: 'salary_plus_commission', label: 'Salary + Commission', description: 'Base salary + per-order %', color: 'amber', count: salesReps?.filter(r => r.commission?.structure === 'salary_plus_commission').length || 0 }
                    ].map(item => (
                        <div key={item.structure} className={`p-4 rounded-lg bg-${item.color}-50 dark:bg-${item.color}-900/20 border border-${item.color}-200 dark:border-${item.color}-800`}>
                            <p className="font-medium text-gray-900 dark:text-white">{item.label}</p>
                            <p className="text-sm text-gray-500">{item.description}</p>
                            <p className="text-2xl font-bold mt-2">{item.count}</p>
                            <p className="text-xs text-gray-500">reps</p>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default CommissionSettings;
